"""Per-cell summands of the additive chi-square-family statistic S = sum_ij s(O_ij, E_ij).

The paper (Section 2.1) only requires the statistic to be *additive over cells*; the
engine keeps the summand pluggable (Section 3.2 closing paragraph, requirement R12).
Expected counts under independence given both margins are E_ij = a_i b_j / N (A5).
"""

import math

import numpy as np

SQRT_FLOOR_TERM = 3.0 / 8.0  # Anscombe / Haldane-Anscombe continuity offset


def expected_counts(row_margins, col_margins):
    """E_ij = a_i * b_j / N (independence MLE given both margins)."""
    a = np.asarray(row_margins, dtype=float)
    b = np.asarray(col_margins, dtype=float)
    N = a.sum()
    return np.outer(a, b) / N


class Summand:
    """A per-cell contribution s(k, E) with a scalar and a vectorized form."""

    def __init__(self, name, scalar, vector, note=""):
        self.name = name
        self._scalar = scalar
        self._vector = vector
        self.note = note

    def cell(self, k, E):
        return self._scalar(k, E)

    def table(self, counts, E):
        return self._vector(np.asarray(counts, dtype=float), E)

    def total(self, counts, E):
        """S for one whole table (used by the enumerator)."""
        return float(np.sum(self._vector(np.asarray(counts, dtype=float), E)))

    def __repr__(self):
        return "Summand(%r)" % (self.name,)


def _anscombe_scalar(k, E):
    # variance-stabilized (Anscombe-root) summand; factor 4 makes it agree with
    # (O-E)^2/E to first order and keeps every atom nonnegative.
    return 4.0 * (math.sqrt(k + SQRT_FLOOR_TERM) - math.sqrt(E + SQRT_FLOOR_TERM)) ** 2


def _anscombe_vector(o, E):
    return 4.0 * (np.sqrt(o + SQRT_FLOOR_TERM) - np.sqrt(E + SQRT_FLOOR_TERM)) ** 2


def _pearson_scalar(k, E):
    d = k - E
    return d * d / E


def _pearson_vector(o, E):
    d = o - E
    return d * d / E


def _g2_scalar(k, E):
    if k == 0.0:
        return 0.0  # 0 log 0 = 0
    return 2.0 * k * math.log(k / E)


def _g2_vector(o, E):
    out = np.zeros_like(o, dtype=float)
    m = o > 0
    out[m] = 2.0 * o[m] * np.log(o[m] / float(E))
    return out


CR_LAM = 2.0 / 3.0
CR_SCALE = 2.0 / (CR_LAM * (CR_LAM + 1.0))


def _cr23_scalar(k, E):
    if k == 0.0:
        return 0.0  # O * ((O/E)^lam - 1) -> 0
    return CR_SCALE * k * ((k / E) ** CR_LAM - 1.0)


def _cr23_vector(o, E):
    out = 1.0 / CR_SCALE  # placeholder, overwritten below
    q = np.zeros_like(o, dtype=float)
    m = o > 0
    q[m] = CR_SCALE * o[m] * ((o[m] / float(E)) ** CR_LAM - 1.0)
    out = q
    return out


