"""Minimal chi-square CDF / quantile (regularized incomplete gamma), no scipy needed.

Used only by the optional moment-matched (Patnaik) chi-square reference: the exact
conditional tail at the fitted 0.95 quantile.  Series and continued-fraction forms
from the standard Numerical-Recipes gser/gcf pair.
"""

import math

ITMAX = 300
EPS = 3.0e-16
FPMIN = 1.0e-300


def _gser(a, x):
    if x <= 0.0:
        return 0.0
    ap = a
    s = 1.0 / a
    dl = s
    for _ in range(ITMAX):
        ap += 1.0
        dl *= x / ap
        s += dl
        if abs(dl) < abs(s) * EPS:
            break
    return s * math.exp(-x + a * math.log(x) - math.lgamma(a))


def _gcf(a, x):
    b = x + 1.0 - a
    c = 1.0 / FPMIN
    d = 1.0 / b
    h = d
    for i in range(1, ITMAX + 1):
        an = -i * (i - a)
        b += 2.0
        d = an * d + b
        if abs(d) < FPMIN:
            d = FPMIN
        c = b + an / c
        if abs(c) < FPMIN:
            c = FPMIN
        d = 1.0 / d
        dl = d * c
        h *= dl
        if abs(dl - 1.0) < EPS:
            break
    return math.exp(-x + a * math.log(x) - math.lgamma(a)) * h


def gamma_p(a, x):
    """Regularized lower incomplete gamma P(a, x)."""
    if x < 0.0 or a <= 0.0:
        raise ValueError("bad arguments")
    if x < a + 1.0:
        return _gser(a, x)
    return 1.0 - _gcf(a, x)


def chi2_cdf(x, df):
    if x <= 0.0:
        return 0.0
    return gamma_p(0.5 * df, 0.5 * x)


def chi2_ppf(p, df, iters=200):
    """Quantile by bisection on the CDF (monotone, so this is robust)."""
    lo, hi = 0.0, max(10.0, df)
    while chi2_cdf(hi, df) < p:
        hi *= 2.0
    for _ in range(iters):
        mid = 0.5 * (lo + hi)
        if chi2_cdf(mid, df) < p:
            lo = mid
        else:
            hi = mid
        if hi - lo <= 1e-15 * max(1.0, hi):
            break
    return 0.5 * (lo + hi)

