"""Read the paper's own reported reference values out of the paper text at run time.

No paper value is ever typed into this code or into results/metrics.json: the numbers
used for the PASS/FAIL comparison are parsed from paper/paper.txt (the paper's
Section 2.2 sentence quoted in the claim contract).  If the text is not present the
comparison is simply reported as unavailable and the internal audits decide the verdict.
"""

import os
import re

_PATTERNS = {
    "max_rel_err": r"maximum relative error of\s+([0-9.]+e[-+]?[0-9]+)",
    "dp_time_ms": r"[0-9.]+e[-+]?[0-9]+\s+in\s+([0-9.]+)\s+milliseconds",
}


def _paper_path():
    here = os.path.dirname(os.path.abspath(__file__))
    root = os.path.dirname(here)
    for cand in (
        os.path.join(root, "paper", "paper.txt"),
        os.path.join(os.getcwd(), "paper", "paper.txt"),
    ):
        if os.path.exists(cand):
            return cand
    return None


def paper_reported_reference():
    """{'max_rel_err': float|None, 'dp_time_ms': float|None, 'source': path}."""
    out = {"max_rel_err": None, "dp_time_ms": None, "source": None}
    path = _paper_path()
    if path is None:
        return out
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    out["source"] = path
    for key, pat in _PATTERNS.items():
        m = re.search(pat, text)
        if m:
            out[key] = float(m.group(1))
    return out

